<?php include '_layout_start.php'; $pdo=db(); if($pdo){$total=$pdo->query('SELECT COUNT(*) c FROM leads')->fetch()['c']; $hot=$pdo->query("SELECT COUNT(*) c FROM leads WHERE lead_temperature='Hot'")->fetch()['c']; $today=$pdo->query("SELECT COUNT(*) c FROM leads WHERE DATE(created_at)=CURDATE()")->fetch()['c']; $admission=$pdo->query("SELECT COUNT(*) c FROM leads WHERE status='Admission Done'")->fetch()['c'];} else {$leads=fallback_leads(); $total=count($leads); $hot=count(array_filter($leads,fn($l)=>($l['lead_temperature']??'')==='Hot')); $today=count(array_filter($leads,fn($l)=>substr($l['created_at']??'',0,10)===date('Y-m-d'))); $admission=count(array_filter($leads,fn($l)=>($l['status']??'')==='Admission Done'));} ?><h1>CRM Dashboard</h1><div class="row g-4 my-2"><div class="col-md-3"><div class="metric"><small>Total Leads</small><h2><?= h($total) ?></h2></div></div><div class="col-md-3"><div class="metric"><small>Today</small><h2><?= h($today) ?></h2></div></div><div class="col-md-3"><div class="metric"><small>Hot Leads</small><h2><?= h($hot) ?></h2></div></div><div class="col-md-3"><div class="metric"><small>Admission Done</small><h2><?= h($admission) ?></h2></div></div></div><div class="lead-box mt-4"><h4>Next Steps</h4><ul><li>Import database/install.sql.</li><li>Update includes/config.php with live database credentials.</li><li>Change default admin password immediately.</li><li>Connect WhatsApp / email OTP API credentials if available.</li></ul></div><?php include '_layout_end.php'; ?>
